  const [draft, setDraft] = useState(''); const [mode, setMode] = useState('general'); const [webSearch, setWebSearch] = useState(false); const [searchChats, setSearchChats] = useState(''); const [searchModels, setSearchModels] = useState(''); const [models, setModels] = useState([]); const [picker, setPicker] = useState(false); const [chatSettings, setChatSettings] = useState(false); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [historyTrimmed, setHistoryTrimmed] = useState(false); const [hasKey, setHasKey] = useState(false); const [loadingChat, setLoadingChat] = useState(false); const [showChatList, setShowChatList] = useState(!id); const [compareFor, setCompareFor] = useState(null); const [compareModel, setCompareModel] = useState('');
